var jsonl={parse:function(e){var t=e.trim();if(!t)return[];var n=t.split("\n"),i=[];for(var s=0;s<n.length;s++){var o=n[s].trim();if(o)try{i.push(JSON.parse(o))}catch(u){throw new Error("Invalid JSON at line "+(s+1))}}return i},stringify:function(e){var t=[];for(var n=0;n<e.length;n++)t.push(JSON.stringify(e[n]));return t.join("\n")}};